import {escapeHTML as e,uid} from './store.js';
import {richText,textValue} from './formatting.js';
export const loreCategories=[
 ['territory','Territórios e cidades','Limites, relevo, clima e lugares importantes.',['Geografia e fronteiras','Clima e recursos naturais','Cidades, rotas e infraestrutura','Riscos e pontos de interesse']],
 ['peoples','Povos e população','Quem vive aqui e como as comunidades se organizam.',['População e distribuição','Povos e identidade cultural','Estrutura social e costumes','Relações entre comunidades']],
 ['language','Línguas e escrita','Vozes, nomes e formas de registrar conhecimento.',['Falantes e regiões','Sons, escrita e nomes','Dialetos e línguas de contato','Educação e transmissão']],
 ['migration','Migrações e diásporas','Jornadas que transformam o mapa e seus habitantes.',['Origem e destino','Causas e período','Rotas, barreiras e acolhimento','Consequências culturais e políticas']],
 ['magic','Sistemas mágicos','Regras claras para o extraordinário.',['Origem e acesso à magia','Regras e limites','Custos, riscos e consequências','Instituições e impacto na sociedade']],
 ['politics','Política e poder','Leis, instituições e disputas internas.',['Governo e sucessão','Leis, direitos e justiça','Facções e disputas pelo poder','Participação e legitimidade']],
 ['geopolitics','Geopolítica e diplomacia','Como os territórios se relacionam.',['Nações e interesses estratégicos','Alianças, tratados e rivalidades','Fronteiras disputadas e conflitos','Comércio, recursos e dependências']],
 ['economy','Economia e comércio','O que sustenta a vida e circula entre as terras.',['Produção e recursos','Moedas, impostos e desigualdade','Rotas e mercados','Trabalho, guildas e tecnologia']],
 ['faith','Religiões e cosmologia','Crenças, mitos e o lugar do mundo no cosmos.',['Divindades e origem do mundo','Ritos, festas e lugares sagrados','Instituições e influência','Crenças divergentes e tabus']],
 ['culture','Cultura e cotidiano','Os detalhes que dão vida ao seu cenário.',['Família, educação e valores','Alimentação, vestuário e moradia','Artes, festas e tradições','Calendário e vida cotidiana']],
 ['ecology','Ecologia e criaturas','Relações entre ambiente, fauna e magia.',['Biomas e ecossistemas','Fauna, flora e cadeia alimentar','Espécies mágicas e adaptação','Catástrofes, conservação e equilíbrio']],
 ['history','História e eras','As marcas do passado no mundo atual.',['Eras e acontecimentos fundadores','Impérios, guerras e transformações','Memórias, fontes e versões do passado','Legados e mistérios não resolvidos']],
 ['buildings','Construções e arquitetura','Edifícios com função, história e identidade.',['Função, localização e habitantes','Materiais, estilo e técnicas','Defesas, acessos e organização interna','História, segredos e significado']],
 ['technology','Tecnologia e conhecimento','Descobertas e seus efeitos sobre a sociedade.',['Nível técnico e fontes de energia','Ciência, medicina e transporte','Acesso ao conhecimento','Invenções e impacto da magia']]
];
export function mountAtlasLore(host,map,{modal,field,save,confirmDelete,openDocument,initialId}){
 if(!Array.isArray(map.lore))map.lore=[];let category='',query='';
 const label=key=>loreCategories.find(c=>c[0]===key)?.[1]||'Registro';
 host.innerHTML=`<section class="atlas-lore"><div class="section-heading"><div><span class="eyebrow">ALÉM DAS FRONTEIRAS</span><h2>Construa este mundo</h2><p>Povos, sistemas e histórias vinculados a ${e(map.name)}.</p></div><button type="button" class="button" data-new-lore>＋ Novo registro</button></div><div class="atlas-lore-layout"><nav class="atlas-categories" aria-label="Categorias do atlas"><button type="button" data-category="">Todos os registros</button>${loreCategories.map(([key,title])=>`<button type="button" data-category="${key}">${title}<small>${map.lore.filter(r=>r.category===key).length}</small></button>`).join('')}</nav><div><input class="atlas-search" type="search" placeholder="Buscar no atlas…" aria-label="Buscar construção de mundo"><div class="atlas-records"></div></div></div></section>`;
 function draw(){host.querySelectorAll('[data-category]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.category===category));const count=b.querySelector('small');if(count)count.textContent=map.lore.filter(r=>r.category===b.dataset.category).length;});const found=map.lore.filter(r=>(!category||r.category===category)&&(r.title+' '+textValue(r.description)).toLocaleLowerCase('pt-BR').includes(query));host.querySelector('.atlas-records').innerHTML=found.map(r=>`<button type="button" class="atlas-record" data-record="${e(r.id)}"><small>${e(label(r.category))}</small><h3>${e(r.title)}</h3><p>${e(textValue(r.description).slice(0,140)||'Abra para desenvolver este registro.')}</p><span>${e(r.region?map.pins.find(p=>p.id===r.region)?.name||'Região removida':'Todo o mapa')} ↗</span></button>`).join('')||`<div class="atlas-empty"><h3>${category?e(label(category)):'O mundo começa nos detalhes'}</h3><p>${e(loreCategories.find(c=>c[0]===category)?.[2]||'Escolha uma categoria e crie seu primeiro registro. Você pode relacioná-lo a uma região do mapa.')}</p><button type="button" class="button ghost" data-empty-new>＋ Criar registro</button></div>`;host.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>read(b.dataset.record));host.querySelector('[data-empty-new]')?.addEventListener('click',()=>edit());}
 function read(id){const r=map.lore.find(r=>r.id===id);if(!r)return;modal(r.title,`<article class="atlas-detail"><span class="eyebrow">${e(label(r.category))}</span><div class="rich-prose">${richText(r.description)}</div>${Object.entries(r.sections||{}).map(([title,value])=>`<section><h3>${e(title)}</h3><div class="rich-prose">${richText(value||'Ainda não definido.')}</div></section>`).join('')}${r.region?`<button type="button" class="button ghost" data-open-region>⌖ Ver região no mapa</button>`:''}<div class="atlas-detail-actions"><button type="button" class="button" data-edit-lore>Editar registro</button><button type="button" class="text-link" data-delete-lore>Excluir registro</button></div></article>`,()=>{},{noActions:true});document.querySelector('[data-edit-lore]').onclick=()=>edit(r);document.querySelector('[data-delete-lore]').onclick=()=>{document.querySelector('#modal').close();confirmDelete('Excluir registro do atlas?',`O registro “${e(r.title)}” será removido.`,()=>{map.lore=map.lore.filter(x=>x.id!==id);});};document.querySelector('[data-open-region]')?.addEventListener('click',()=>{document.querySelector('#modal').close();openDocument(r.region);});}
 function edit(r){const cat=r?.category||category||'territory',draft={...(r?.sections||{})};modal(r?'Editar registro do atlas':'Novo registro do atlas',`<div class="atlas-form">${field('Nome do registro','title',r?.title||'','text',true)}<div class="field-grid"><label class="field"><span>Categoria</span><select name="category">${loreCategories.map(([key,title])=>`<option value="${key}" ${key===cat?'selected':''}>${title}</option>`).join('')}</select></label><label class="field"><span>Região relacionada</span><select name="region"><option value="">Todo o mapa</option>${map.pins.map(p=>`<option value="${e(p.id)}" ${p.id===r?.region?'selected':''}>${e(p.name)}</option>`).join('')}</select></label></div>${field('Visão geral','description',r?.description||'','textarea')}<div class="atlas-section-fields"></div></div>`,fd=>{capture();const key=String(fd.get('category')),titles=loreCategories.find(c=>c[0]===key)[3];const data={id:r?.id||uid(),title:String(fd.get('title')).trim(),category:key,region:String(fd.get('region')),description:String(fd.get('description')),sections:Object.fromEntries(titles.map(t=>[t,draft[t]||'']))};if(!data.title)throw Error('Informe um nome.');if(r)Object.assign(r,data);else map.lore.push(data);save();draw();});const form=document.querySelector('.atlas-form'),select=form.querySelector('[name=category]'),fields=form.querySelector('.atlas-section-fields');function capture(){fields.querySelectorAll('textarea').forEach(t=>draft[t.dataset.section]=t.value);}function sections(){fields.innerHTML=loreCategories.find(c=>c[0]===select.value)[3].map((title,i)=>`<label class="field"><span>${e(title)}</span><textarea name="lore_${i}" data-rich="true" data-section="${e(title)}">${e(draft[title]||'')}</textarea></label>`).join('');}select.onchange=()=>{capture();sections();};sections();}
 host.querySelector('[data-new-lore]').onclick=()=>edit();host.querySelector('.atlas-search').oninput=ev=>{query=ev.target.value.toLocaleLowerCase('pt-BR');draw();};host.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;draw();});draw();if(initialId)read(initialId);
}
